Definition ipf_entry_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe) (P IN E p0 lo shi : Z) (bs : list byte) (c : pcore) (pad7 pad2 : list byte) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists (spa : Z) (gsz : nat) (gj : list byte) (ff fp : Z) (h3 : word) (j0 j128 jr jh : list byte),
       ipf_bpure sp spa gsz P IN E lo shi c p0 (p0 + Z.of_nat (length bs)) bs
    /\ ipf_segA_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF spa gsz gj P IN E p0 lo shi ff fp
                     (p0 + Z.of_nat (length bs)) bs c pad7 pad2 p0 p0 (wz 0x41b58ab3) (wz 0x13fb2) (wz 0xd0474) h3 j0 j128 jr jh m ms'.
