  rw_cells asegs m P (ParserCoreCells c pad7 pad2) -> rw_cells asegs m IN [C8 (wz p0)] -> rw_cells asegs m E (ErrCodeCells EC_clear) ->
  bytes_at asegs m p0 bs -> APfTab m -> (AFieldTabZero m \/ FT m) -> FTInit m -> AHttpCat m g -> AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp) -> mem_inv asegs m -> bv_unsigned ra mod 2 = 0 -> tp = Z_to_bv 64 ATP ->
  athr_cells m -> ACONST m -> stack0 m lo shi -> as_RFS H LF m -> (length LF < AFS7_MAXLIVE)%nat -> (length LF + 2 < AFS_MAXLIVE)%nat ->
  ipf_pure sp P IN E lo shi c p0 bs ->
  aapp P 256 -> aapp E 24 -> aapp p0 (Z.of_nat (length bs)) ->
  fsobj H LF P 256 -> fsobj H LF E 24 -> fsobj H LF p0 (Z.of_nat (length bs)) ->
