  evt asegs (ipf_entry_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF P IN E p0 lo shi bs c pad7 pad2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_INNER_PARSE_FIELDS) fc None m (seg_rom asegs)).
